    if (e.kind === "gain") out.push({ type: "gain", text: e.name + (e.amount > 1 ? " \xD7" + e.amount : "") });
    else if (e.kind === "loss") out.push({ type: "loss", text: e.name + (e.amount > 1 ? " \xD7" + e.amount : "") });
    else if (e.kind === "unlock") out.push({ type: "unlock", text: e.name });
