const imNL = String.fromCharCode(10);
let imPret = false, imGroupe = null, imDerniere = 0, imDernierLeger = 0;
const imOff = { y: 0, p: 0 };
const imU = { t: { value: 0 }, z: { value: [] }, q: { value: [] } };
