    el.style.cssText = 'position:absolute;transform:translate(-50%,-100%);cursor:pointer;z-index:6;width:' + Math.round(140 * (o.p.taille || 1) * navEchelle(o.c.pitch || 0)) + 'px';
    ['pointerdown', 'pointerup', 'touchstart'].forEach(function(t){ el.addEventListener(t, function(e){ e.stopPropagation(); }); });
