/*  L'orientation de l'appareil pilote la camera : on garde l'ecart a la
    position du telephone au moment ou on l'active, ajoute au regard de
    ce moment-la. Portrait : tourner sur soi (alpha) et lever le
    telephone (beta) ; paysage : gamma remplace beta.                */
let sceneGyroH = null;
function sceneGyro(on){
  if(sceneGyroH){ window.removeEventListener('deviceorientation', sceneGyroH); sceneGyroH = null; }
  if(!on) return Promise.resolve(false);
  const DOE = window.DeviceOrientationEvent;
  if(!DOE) return Promise.resolve(false);
  const branche = function(){
    let base = null;
    sceneGyroH = function(e){
      if(e.alpha == null || e.beta == null) return;
      const ang = (screen.orientation && typeof screen.orientation.angle === 'number') ? screen.orientation.angle : (window.orientation || 0);
      const paysage = ang === 90 || ang === -90 || ang === 270;
      const haut = paysage ? (ang === 90 ? -e.gamma : e.gamma) : e.beta;
      if(!base){ base = { a: e.alpha, h: haut, yaw: yaw, pitch: pitch }; return; }
      let da = e.alpha - base.a; if(da > 180) da -= 360; if(da < -180) da += 360;
      yaw = base.yaw + da * Math.PI / 180;
      const lim = Math.PI / 2 - 0.05;
      pitch = Math.max(-lim, Math.min(lim, base.pitch + (haut - base.h) * Math.PI / 180));
      try{ needsRedraw(); }catch(err){}
    };
    window.addEventListener('deviceorientation', sceneGyroH);
    return true;
  };
  /*  iPhone : il faut la permission, demandee pendant le geste.      */
  if(typeof DOE.requestPermission === 'function'){
    return DOE.requestPermission().then(function(r){ return r === 'granted' ? branche() : false; }).catch(function(){ return false; });
  }
  return Promise.resolve(branche());
}
